}

function getValue(lines, key) {
  const expression = new RegExp(
    `^\\s*(?:-\\s*)?${key}:\\s*(.*?)\\s*$`
  );

  for (const line of lines) {
    if (isIgnoredLine(line)) {
      continue;
    }

    const match = line.match(expression);

    if (!match) {
      continue;
    }

    const raw = match[1]
      .replace(/\s+#.*$/, '')
      .trim();

    if (!raw) {
      return null;
    }

    return raw.replace(/^["']|["']$/g, '');
  }

  return null;
}

function getNumber(lines, key) {
  const raw = getValue(lines, key);

  if (raw === null || !/^\d+$/.test(raw)) {
    return null;
  }

  const value = Number(raw);

  return Number.isInteger(value)
    ? value
    : null;
}

function getBlock(lines, key) {
  const expression = new RegExp(
    `^\\s*${key}:\\s*(?:#.*)?$`
  );

  const start = lines.findIndex(line =>
    !isIgnoredLine(line) &&
    expression.test(line)
  );

  if (start < 0) {
    return [];
  }

  const baseIndent = indentOf(lines[start]);
  const result = [];

  for (let i = start + 1; i < lines.length; i++) {
    const line = lines[i];

    if (isIgnoredLine(line)) {
      continue;
    }

    const currentIndent = indentOf(line);
    const isListItem = /^\s*-\s/.test(line);

    if (currentIndent < baseIndent) {
      break;
    }

    if (
      currentIndent === baseIndent &&
      !isListItem
    ) {
      break;
    }

    result.push(line);
  }

  return result;
}

function getFirstListItem(lines) {
  const indexes = lines
    .map((line, index) => ({
      line,
      index,
      indent: indentOf(line),
    }))
    .filter(item =>
      /^\s*-\s/.test(item.line)
    );

  if (indexes.length === 0) {
    return [];
  }

  const firstIndent = Math.min(
    ...indexes.map(item => item.indent)
  );

  const first = indexes.find(item =>
    item.indent === firstIndent
  );

  const result = [];

  for (let i = first.index; i < lines.length; i++) {
    const line = lines[i];

    if (isIgnoredLine(line)) {
      continue;
    }

    if (i !== first.index) {
      const currentIndent = indentOf(line);

      if (currentIndent < firstIndent) {
        break;
      }

      if (
        currentIndent === firstIndent &&
        /^\s*-\s/.test(line)
      ) {
        break;
      }
    }

    result.push(line);
  }

  return result;
}

function parseResources(containerLines) {
  const resourcesBlock = getBlock(
    containerLines,
    'resources'
  );

  if (resourcesBlock.length === 0) {
    return null;
  }

  const requestsBlock = getBlock(
    resourcesBlock,
    'requests'
  );

  const limitsBlock = getBlock(
    resourcesBlock,
    'limits'
  );

  return {
    requests: {
      cpu: getValue(requestsBlock, 'cpu'),
      memory: getValue(requestsBlock, 'memory'),
    },
    limits: {
      cpu: getValue(limitsBlock, 'cpu'),
      memory: getValue(limitsBlock, 'memory'),
    },
  };
}

function getContainersBlock(lines, kind) {
  let workloadLines = lines;

  if (kind === 'CronJob') {
    workloadLines = getBlock(
      lines,
      'jobTemplate'
    );
  }

  const containersBlock = getBlock(
    workloadLines,
    'containers'
  );

  return getFirstListItem(containersBlock);
}

function parseWorkload(lines, kind, name, sourceFile) {
  const container = getContainersBlock(
    lines,
    kind
  );

  const portsBlock = getBlock(
    container,
    'ports'
  );

  const firstPort = getFirstListItem(
    portsBlock
  );

  const image = getValue(
    container,
    'image'
  );

  const containerPort = getNumber(
    firstPort,
    'containerPort'
  );

  const resources = parseResources(
    container
  );

  const spec = getBlock(
    lines,
    'spec'
  );

  const replicas = getNumber(
    spec,
    'replicas'
  );

  return {
    kind,
    name,
    sourceFile,
    image,
    containerPort,
    resources,
    replicas,
  };
}

function parseService(lines, name, sourceFile) {
  const spec = getBlock(
    lines,
    'spec'
  );

  const portsBlock = getBlock(
    spec,
    'ports'
  );

  const firstPort = getFirstListItem(
    portsBlock
  );

  const rawTargetPort = getValue(
    firstPort,
    'targetPort'
  );

  let targetPort = null;

  if (rawTargetPort !== null) {
    targetPort = /^\d+$/.test(rawTargetPort)
      ? Number(rawTargetPort)
      : rawTargetPort;
  }

  return {
    kind: 'Service',
    name,
    sourceFile,
    servicePort: getNumber(
      firstPort,
      'port'
    ),
    targetPort,
    serviceType: getValue(
      spec,
      'type'
    ),
  };
}

function parseDocument(content, sourceFile) {
  const lines = content.split(/\r?\n/);

  const kind = getValue(
    lines,
    'kind'
  );

  if (!kind) {
    return null;
  }

  const metadataBlock = getBlock(
    lines,
    'metadata'
  );

  const name = getValue(
    metadataBlock,
    'name'
  );

  if (!name) {
    return null;
  }

  if (WORKLOAD_KINDS.has(kind)) {
    return parseWorkload(
      lines,
      kind,
      name,
      sourceFile
    );
  }

  if (kind === 'Service') {
    return parseService(
      lines,
      name,
      sourceFile
    );
  }

  return {
    kind,
    name,
    sourceFile,
  };
}

