  for (const file of candidates) {
    for (const rule of RULES) {
      findings.push(
        ...extractMatches(file, rule)
      );
    }
  }

  return findings;
}

function filterNestedComponents(component, findings) {
  const root = normalizePath(component.rootPath);

  const otherRoots = components
    .filter(other => other !== component)
    .map(other => normalizePath(other.rootPath))
    .filter(otherRoot =>
      otherRoot &&
      otherRoot !== '.' &&
      (
        root === '.' ||
        otherRoot.startsWith(`${root}/`)
      )
    );

  return findings.filter(finding =>
    !otherRoots.some(otherRoot =>
      finding.sourceFile.startsWith(`${otherRoot}/`)
    )
  );
}

function resolvePort(findings) {
  if (findings.length === 0) {
    return {
      value: null,
      source: null,
      conflict: false
    };
  }

  const priority = Math.min(
    ...findings.map(item => item.priority)
  );

  const selected = findings.filter(
    item => item.priority === priority
  );

  const values = [
    ...new Set(selected.map(item => item.value))
  ];

  if (values.length !== 1) {
    return {
      value: null,
      source: null,
      conflict: true
    };
  }

  return {
    value: values[0],
    source: selected[0],
    conflict: false
  };
}

function enrichComponent(component) {
  const allFindings = collectEvidence(component);

  const findings = filterNestedComponents(
    component,
    allFindings
  );

  const resolved = resolvePort(findings);

  const existing = isObject(component.kubernetes)
    ? component.kubernetes
    : null;

  const kubernetesPort =
    existing?.containerPort ?? null;

  const selectedPort =
    kubernetesPort ?? resolved.value;

  const manifestSource =
    existing?.manifestPaths?.[0] ?? null;

  let portEvidence = null;

  if (
    kubernetesPort !== null &&
    manifestSource
  ) {
    portEvidence = {
      sourceFile: manifestSource,
      origin: 'KUBERNETES_MANIFEST',
      confidence: 'HIGH',
      requiresReview:
        existing?.requiresReview ?? true
    };
  } else if (
    kubernetesPort === null &&
    resolved.source
  ) {
    portEvidence = {
      sourceFile: resolved.source.sourceFile,
      origin: resolved.source.origin,
      confidence: resolved.source.confidence,
      requiresReview: true,
      line: resolved.source.line
    };
  } else if (
    isObject(existing?.portEvidence)
  ) {
    portEvidence = existing.portEvidence;
  }

  const hasEvidence =
    Boolean(existing) ||
    findings.length > 0;

  let enriched = {
    ...component
  };

  if (hasEvidence) {
    enriched = {
      ...component,
      kubernetes: {
        containerPort: selectedPort,
        servicePort:
          existing?.servicePort ?? null,
        targetPort:
          existing?.targetPort ?? null,
        image:
          existing?.image ?? null,
        resources:
          existing?.resources ?? null,
        manifestPaths:
          existing?.manifestPaths ?? [],
        requiresReview:
          existing?.requiresReview ?? true,

        ...(portEvidence
          ? { portEvidence }
          : {})
      }
    };
  }

  return {
    component: enriched,
    evidence: {
      name: component.name,
      rootPath: component.rootPath,
      detectedPort: resolved.value,
      effectivePort: selectedPort,
      origin:
        portEvidence?.origin ?? null,
      sourceFile:
        portEvidence?.sourceFile ?? null,
      confidence:
        portEvidence?.confidence ?? null,
      conflict: resolved.conflict,
      requiresReview:
        existing?.requiresReview === true ||
        resolved.conflict ||
        (
          selectedPort !== null &&
          kubernetesPort === null
        ),
      portEvidence,
      findings
    }
  };
}

const results = components.map(enrichComponent);

const enrichedComponents = results.map(
  item => item.component
);

const applicationEvidence = {
  version: 'APPLICATION_EVIDENCE_V2',
  scannedFiles: sourceFiles.length,
  componentCount: results.length,

  detectedPorts: results.filter(
    item => item.evidence.detectedPort !== null
  ).length,

  effectivePorts: results.filter(
    item => item.evidence.effectivePort !== null
  ).length,

  conflicts: results.filter(
    item => item.evidence.conflict
  ).length,

  components: results.map(item => item.evidence)
};

return [
  {
    json: {
      ...input,

      completeBody: {
        ...completeBody,
        components: enrichedComponents
      },

      applicationEvidence
    }
  }
];
